<script lang="ts">
  import { onMount } from 'svelte';
  import { AREAS, indexGuideline, loadGuideline, markReady, readHash, writeHash, type Guideline, type HashState, type Doc } from '../../shared/data.js';
  let g = $state.raw<Guideline | null>(null);
  let state = $state.raw<HashState>(readHash());
  let query = $state('');
  let error = $state('');
  onMount(() => {
    const onHash = () => { state = readHash(); if (state.view === 'explore') query = state.query; };
    addEventListener('hashchange', onHash);
    onHash();
    void loadGuideline().then(data => g = data).catch(e => error = String(e));
    return () => removeEventListener('hashchange', onHash);
  });
  $effect(() => { if (g || error) { void state; queueMicrotask(markReady); } });
  const ix = $derived(g ? indexGuideline(g) : null);
  const question = $derived(g && state.view === 'trace' ? g.questions.find(q => q.id === state.question) : null);
  const selectedDoc = $derived(ix && state.view === 'rule' ? ix.docs.get(state.document) : null);
  const selectedSentence = $derived(ix && state.view === 'rule' ? ix.sentence(`${state.document}:${state.sentence}`) : null);
  const rule = $derived(ix && state.view === 'rule' ? ix.rules.get(`${state.document}:${state.sentence}`) : null);
  const found = $derived(g && state.view === 'explore' ? g.documents.filter(d => `${d.id} ${d.source} ${d.sentences.map(s => s.ace).join(' ')}`.toLowerCase().includes(state.query.toLowerCase())) : []);
  const lit = $derived(new Set(question?.statements.map(s => ix?.docs.get(s.document)?.rec) ?? (selectedDoc ? [selectedDoc.rec] : state.view === 'explore' ? found.map(d => d.rec) : [])));
  function go(next: HashState) { state = next; writeHash(next); }
  const excerpt = (s: string, n = 115) => s.length > n ? `${s.slice(0, s.lastIndexOf(' ', n))}…` : s;
  const openDoc = (d: Doc) => go({view: 'rule', document: d.id, sentence: d.sentences[0]?.n ?? 1});
</script>

<main>
  <header><div><a class="brand" href="#overview" onclick={() => go({view:'overview'})}>CNL / CKC <span>Graph study</span></a><h1>Guideline in care order</h1><p>Four clinical areas. Twelve recommendations. Every branch leads to the source.</p></div><button onclick={() => go({view:'overview'})}>Show overview</button></header>
  {#if error}<p role="alert">{error}</p>{:else if !g || !ix}<p>Loading the guideline…</p>{:else}
    <div class="tools"><label>Trace a question<select value={question?.id ?? ''} onchange={e => e.currentTarget.value && go({view:'trace',question:e.currentTarget.value})}><option value="">Choose an answer</option>{#each g.questions as q}<option value={q.id}>{q.question}</option>{/each}</select></label><form onsubmit={e => {e.preventDefault();go({view:'explore',query});}}><label for="search">Explore the knowledge base</label><div class="search"><input id="search" bind:value={query} placeholder="Find a term, for example naloxone"/><button>Find sentences</button></div></form></div>
    <p class="notice">{g.derivation}</p>
    <p class="legend"><span class="dot"></span> Node: recommendation. Branch: contains rules and documents. <strong>Blue: selected citations.</strong> Area order is editorial, not a patient pathway.</p>
    {#if state.view === 'trace'}
      {#if question}<section class="reading"><h2>{question.question}</h2><p>{question.statements.length} statements, in answer order. Select a statement to read its rule and source.</p><ol class="trace">{#each question.statements as s}{@const doc = ix.docs.get(s.document)}<li><button class="statement" onclick={() => go({view:'rule',document:s.document,sentence:s.sentence})}>{ix.sentence(`${s.document}:${s.sentence}`)?.ace ?? 'Sentence unavailable'}</button><small>{s.document}, sentence {s.sentence} <a href={`${g.pdf}#page=${doc?.page}`} target="_blank" rel="noreferrer">Page {doc?.page}</a></small></li>{/each}</ol><details><summary>Prolog goal used by the live demo</summary><pre>{question.goal}</pre></details></section>{:else}<p role="alert">Question not found: {state.question}</p>{/if}
    {:else if state.view === 'rule'}
      {#if selectedDoc && selectedSentence}<section class="reading rule"><div class="source-head"><h2>Recommendation {selectedDoc.rec ?? 'scope'} / sentence {selectedSentence.n}</h2><a href={`${g.pdf}#page=${selectedDoc.page}`} target="_blank" rel="noreferrer">Read guideline page {selectedDoc.page}</a></div>
      <p class="muted">{rule ? 'Clinical rule from the exported recommendation parse' : 'Text reading: heuristic split, not the KB’s clinical parse'}</p>
      <div class="logic"><div><h3>Condition</h3><p>{rule?.condition ?? selectedSentence.condition ?? 'No explicit condition in this sentence.'}</p></div><div><h3>{rule ? `${rule.subject} / ${rule.mode}` : `${selectedSentence.modal}${selectedSentence.negated ? ' / negated' : ''}`}</h3>{#if rule}{#each rule.actions as a}<p><strong>{a.polarity === 'negative' ? 'not ' : ''}{a.verb}</strong> {a.object} {a.modifiers.map(m => `${m.preposition} ${m.value}`).join(' ')}</p>{/each}{:else}<p>{selectedSentence.conclusion}</p>{/if}</div></div>
      <details><summary>Controlled-language sentence and document source</summary><p>{selectedSentence.ace}</p><blockquote>{selectedDoc.source}</blockquote><small>{selectedDoc.id} / {selectedDoc.section}</small></details></section>{:else}<p role="alert">Sentence not found: {state.document}:{state.sentence}</p>{/if}
    {:else if state.view === 'explore'}<section class="reading"><h2>Explore “{state.query}”</h2><p>{found.length} matching documents. The map highlights their recommendation families.</p><div class="matches">{#each found as d}<details><summary>{d.rec ? `Recommendation ${d.rec}` : 'Guideline-wide'} / {d.kind} / page {d.page}</summary><p>{d.source}</p>{#each d.sentences as s}<button class="statement" onclick={() => go({view:'rule',document:d.id,sentence:s.n})}>Sentence {s.n}: {s.ace}</button>{/each}<button onclick={() => openDoc(d)}>Read this document</button></details>{/each}</div></section>{/if}
    <section class="board" aria-label="Clinical area swimlanes">
      {#each AREAS as area}<section class="lane"><h2>{area.label}</h2><div class="rail">{#each g.recommendations.filter(r => area.recs.includes(r.number as never)) as rec}{@const rules = g.rules.filter(r => r.document === rec.id)}{@const docs = g.documents.filter(d => d.rec === rec.number)}<article class:lit={lit.has(rec.number)}><button class="rec" onclick={() => go({view:'rule',document:rec.id,sentence:rules[0]?.sentence ?? 1})}><span class="rec-number">{rec.number}</span><span><strong>Recommendation {rec.number}</strong><span class="excerpt">{excerpt(rec.source)}</span></span></button><small>{rules.length} rules / {docs.length} documents{rec.grade ? ` / Category ${rec.grade.category}` : ''}</small><details><summary>Rules and documents</summary><div class="nested">{#each rules as r}<button onclick={() => go({view:'rule',document:r.document,sentence:r.sentence})}>Sentence {r.sentence}: {r.mode} {r.actions.map(a => `${a.polarity === 'negative' ? 'not ' : ''}${a.verb} ${a.object}`).join('; ')}</button>{/each}<details><summary>{docs.length} source documents</summary>{#each docs as d}<button onclick={() => openDoc(d)}>{d.id} / page {d.page}</button>{/each}</details></div></details></article>{/each}</div></section>{/each}
    </section>
    <section class="boundaries"><details><summary>Where these recommendations do not apply ({g.exclusions.length} scope records)</summary><p>These records state exclusions. Absence of an exclusion does not establish that a patient belongs to the guideline population.</p>{#each g.exclusions as x}<p><button class="statement" onclick={() => go({view:'rule',document:x.document,sentence:x.sentence})}>{x.ace}</button><small>{x.document}, sentence {x.sentence}</small></p>{/each}</details><details><summary>Superseded statements ({g.supersessions.length})</summary>{#each g.supersessions as s}<p><s>{s.ace}</s><br/><strong>Superseded {String(s.date).slice(0,4)}-{String(s.date).slice(4,6)}-{String(s.date).slice(6)}</strong><br/><a href={s.url} target="_blank" rel="noreferrer">{s.citation}</a><br/><button onclick={() => go({view:'rule',document:s.document,sentence:s.sentence})}>Read original sentence {s.sentence}</button></p>{/each}</details></section>
    <footer>CDC Clinical Practice Guideline for Prescribing Opioids for Pain, 2022. This study is not endorsed by CDC. The source is available free on the CDC website. Prototype only; not for clinical use.</footer>
  {/if}
</main>
<style>
  main{max-width:1500px;margin:auto;padding:30px 32px 40px}header{display:flex;align-items:center;justify-content:space-between;gap:20px}h1{font-size:2.3rem;line-height:1.12;margin:18px 0 8px;font-weight:750;letter-spacing:-.035em}h2{font-size:1.18rem;line-height:1.3;margin:0 0 12px}h3{font-size:1rem;margin:0}p{margin:8px 0 14px;max-width:76ch}.brand{font-weight:750;color:var(--text);text-decoration:none}.brand span{font-weight:400;color:var(--text-muted);margin-left:14px}button,input,select{background:var(--surface-raised);color:var(--text);border:1px solid var(--border);border-radius:3px;padding:8px 10px}button,summary{cursor:pointer}button:hover{background:var(--surface-sunken)}a{color:var(--action)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--focus-ring);outline-offset:3px}.tools{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:24px;padding:18px 0;border-top:1px solid var(--border)}label{display:block;font-weight:650}select{display:block;width:100%;margin-top:5px;font:inherit}.search{display:flex;gap:6px;margin-top:5px}input{min-width:0;flex:1}.notice{font-size:.83rem;color:var(--text-muted);max-width:none}.legend{font-size:.83rem;max-width:none}.legend strong{color:var(--action)}.dot{display:inline-block;width:10px;height:10px;border:2px solid var(--text-muted);border-radius:50%;margin-right:5px}.board{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:var(--surface-raised);border:1px solid var(--border);margin:22px 0}.lane{min-width:0;padding:18px 18px 8px;border-right:1px solid var(--border)}.lane:last-child{border-right:0}.lane>h2{min-height:90px;font-size:1.08rem}.rail{margin-left:9px;border-left:2px solid var(--border);padding-left:15px}article{position:relative;margin:0 0 22px;padding-bottom:12px;border-bottom:1px solid var(--border)}article:before{content:'';position:absolute;width:16px;left:-17px;top:19px;border-top:2px solid var(--border)}.rec{display:flex;gap:9px;text-align:left;width:100%;border:0;padding:0;background:none;line-height:1.35}.rec-number{flex:none;display:grid;place-items:center;width:27px;height:27px;border:1px solid var(--border);border-radius:50%;font-size:.85rem}.excerpt{display:block;margin:7px 0 10px;font-size:.91rem;font-weight:400}.lit:before{border-color:var(--action);border-width:4px}.lit .rec-number{background:var(--action);color:var(--action-text);border-color:var(--action)}.lit .rec strong{color:var(--action)}small{display:block;color:var(--text-muted);font-size:.78rem;overflow-wrap:anywhere}summary{padding:7px 0;line-height:1.4}.nested{padding-left:10px;border-left:2px solid var(--border)}.nested button{display:block;text-align:left;border:0;border-bottom:1px solid var(--border);font-size:.84rem;overflow-wrap:anywhere;width:100%;margin-bottom:5px}.reading{background:var(--surface-raised);border-left:5px solid var(--action);padding:20px 24px;margin:24px 0}.reading h2{font-size:1.4rem}.trace{padding-left:24px;margin-bottom:12px}.trace li{padding:5px 0 13px;max-width:76ch}.statement{border:0;padding:0;text-align:left;color:var(--action);background:none;line-height:1.5}.logic{display:grid;grid-template-columns:1fr 1fr;gap:26px}.logic>div{border-top:2px solid var(--border);padding-top:12px}.source-head{display:flex;gap:20px;justify-content:space-between;align-items:baseline}.muted{color:var(--text-muted);font-size:.85rem}pre{white-space:pre-wrap;overflow-wrap:anywhere}blockquote{margin:14px 0;padding-left:15px;border-left:2px solid var(--border);max-width:76ch}.matches{max-height:320px;overflow:auto}.matches details{border-top:1px solid var(--border);padding:8px 0}.matches .statement{display:block;margin:12px 0}.boundaries{display:grid;grid-template-columns:1fr 1fr;gap:30px;border-top:1px solid var(--border);padding-top:10px}.boundaries>details>summary{font-weight:650}footer{font-size:.78rem;max-width:95ch;color:var(--text-muted);margin-top:30px} @media(max-width:900px){main{padding:22px 18px}.board{grid-template-columns:1fr 1fr}.lane:nth-child(2){border-right:0}.lane{border-bottom:1px solid var(--border)}.tools{gap:14px}.source-head{display:block}}@media(max-width:560px){main{padding:20px 16px}header{display:block}header>button{margin:5px 0}h1{font-size:1.9rem}.tools,.board,.logic,.boundaries{grid-template-columns:1fr}.lane{border-right:0}.lane>h2{min-height:0;margin-bottom:20px}.search{flex-wrap:wrap}.search input{flex-basis:100%}.reading{padding:16px 14px}.reading h2{font-size:1.2rem}.brand span{margin-left:8px}select{max-width:100%;font-size:.9rem}.rec .excerpt{max-width:60ch}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style>
